                if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    def segments(n, divs):
        cuts = [-1] + divs + [n]
        return [(cuts[k] + 1, cuts[k + 1])
                for k in range(len(cuts) - 1)
                if cuts[k] + 1 < cuts[k + 1]]

    bands, panels = segments(h, div_rows), segments(w, div_cols)

    def shape(rspan, cspan, color):
        r0, r1 = rspan
        c0, c1 = cspan
        return {(r-r0, c-c0)
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] == color}

    colors = set(v for row in grid for v in row if v != 0)
    for color in colors:
        # A panel pair is known to be a reflection pair if a band contains
        # nonempty shapes that are mirror images of one another.
        reflected_pairs = set()
        for j in range(len(panels) - 1):
            width = max(panels[j][1] - panels[j][0],
                        panels[j+1][1] - panels[j+1][0])
            for band in bands:
                left = shape(band, panels[j], color)
                right = shape(band, panels[j+1], color)
                mirror = {(dr, width - 1 - dc) for dr, dc in left}
                if left and right and mirror == right:
                    reflected_pairs.add(j)
                    break

        for j in reflected_pairs:
            width = max(panels[j][1] - panels[j][0],
                        panels[j+1][1] - panels[j+1][0])
            for band in bands:
                left = shape(band, panels[j], color)
                right = shape(band, panels[j+1], color)
                if left and not right:
                    r0, r1 = band
                    c0, c1 = panels[j+1]
                    for dr, dc in left:
                        tc = c0 + width - 1 - dc
                        if r0 + dr < r1 and c0 <= tc < c1:
                            out[r0 + dr][tc] = color
                elif right and not left:
                    r0, r1 = band
                    c0, c1 = panels[j]
                    for dr, dc in right:
                        tc = c0 + width - 1 - dc
                        if r0 + dr < r1 and c0 <= tc < c1:
                            out[r0 + dr][tc] = color

